static char sx__str3573[]="usage:";
static char sx__str3574[]="  spectre <command> [args] | <input.sx> [options]";
static char sx__str3575[]="";
static char sx__str3576[]="commands:";
static char sx__str3577[]="  init   <name>        Initialize a new project";
static char sx__str3578[]="  build  <config>      Build using a config from sx.mod";
static char sx__str3579[]="  run    <input.sx>    Compile and immediately run a program";
static char sx__str3580[]="  doc    <path>        Generate docs for a given .sx into ./docs-out/";
static char sx__str3581[]="  add    <git-url>     Clone a git dependency into ./lib/ and record it";
static char sx__str3582[]="  remove <dep-name>    Remove a dependency by repository name";
static char sx__str3583[]="  restore              Restore all dependencies from sx.mod and sx.lock into ./lib/";
static char sx__str3584[]="  graph                Visualize the project dependency tree";
static char sx__str3585[]="  ref                  Generate the language reference in the current directory";
static char sx__str3586[]="  clean                Remove build artifacts";
static char sx__str3587[]="  doctor               Show system and Spectre installation information";
static char sx__str3588[]="";
static char sx__str3589[]="options:";
static char sx__str3590[]="  --ast                Print the AST in a unicode tree and exit";
static char sx__str3591[]="  --syntax-check       Check validity of syntax given some program";
static char sx__str3592[]="  --emit-alt           Print alternative IR to stdout and exit";
static char sx__str3593[]="  --emit-asm           Print assembly to stdout and exit";
static char sx__str3594[]="  --src-target=<os>    Mock target OS for when-blocks in source output";
static char sx__str3595[]="  --translate-c        Translate C input into a single .sx file";
static char sx__str3596[]="  --inc-path=<dir>     Add an include search path for the alt backend";
static char sx__str3597[]="  --show-cmd           Show the command used for linking";
static char sx__str3598[]="  --test               Run the unit tests in the current file";
static char sx__str3599[]="  --release            Build in release mode";
static char sx__str3600[]="  --dll                Build a shared library";
static char sx__str3601[]="  -b, --bootstrap      Display backend output on error";
static char sx__str3602[]="  -c, --compile        Compile only to produce object file, without linking";
static char sx__str3603[]="  -o, --output <file>  Output path for binary or build artifact";
static char sx__str3604[]="  -l, --loud           Show stages of compilation with verbose output";
